cat > /tmp/suggest.js <<'EOF'
const ts = require('/Users/stark/Desktop/work/RN/heals-app-rn/node_modules/typescript');
const path = require('path');
const root = process.argv[2];
const files = require('fs').readFileSync('/tmp/changed_ts.txt','utf8').split('\n').filter(Boolean).filter(f=>!f.includes('contact-us'));
const cfgPath = path.join(root,'tsconfig.json');
const cfg = ts.readConfigFile(cfgPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(cfg.config, ts.sys, root, {module: ts.ModuleKind.ESNext, noEmit: true});
const program = ts.createProgram(parsed.fileNames, parsed.options);
let out = [];
for (const f of files) {
  const sf = program.getSourceFile(path.join(root,f));
  if (!sf) { out.push(`${f}: NOT IN PROGRAM`); continue; }
  const sug = program.getSuggestionDiagnostics ? program.getSuggestionDiagnostics(sf) : [];
  // fallback to language service
  for (const d of sug) {
    const {line} = sf.getLineAndCharacterOfPosition(d.start);
    out.push(`${f}(${line+1}): TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText,'\n')}`);
  }
}
console.log(out.join('\n') || 'none');
console.log('program.getSuggestionDiagnostics available:', typeof program.getSuggestionDiagnostics);
EOF
